"use strict"; // Enforce strict mode for cleaner code execution

/**
 * Helper function to destructure an array into a fixed number of elements.
 * This function is typically generated by transpilers like Babel for array destructuring assignments.
 * @param {Array} inputArray - The array or iterable to destructure.
 * @param {number} limitIndex - The maximum number of elements to extract.
 * @returns {Array} An array containing the extracted elements.
 */
function extractArrayElements(inputArray, limitIndex) {
  // Attempt to use a direct array check, then an iterable conversion, otherwise throw an error.
  return checkIfInputIsArray(inputArray) || convertIterableToArrayWithLimit(inputArray, limitIndex) || throwNonIterableError();
}

/**
 * Throws a TypeError when an attempt is made to destructure a non-iterable instance.
 * This is a utility function often generated by transpilers.
 * @throws {TypeError} If the instance provided for destructuring is not iterable.
 */
function throwNonIterableError() {
  throw new TypeError("Invalid attempt to destructure non-iterable instance");
}

/**
 * Helper function to convert an iterable into an array, with an optional size limit.
 * This function is commonly generated by transpilers to handle iterable protocol.
 * @param {Iterable} sourceIterable - The iterable source to convert.
 * @param {number} maxElements - The maximum number of elements to include in the resulting array.
 * @returns {Array} A new array containing elements from the iterable, up to `maxElements`.
 */
function convertIterableToArrayWithLimit(sourceIterable, maxElements) {
  var resultCollection = []; // Initialize an empty array to accumulate elements
  var iterationCompleted = true; // Flag to track if the iteration finished naturally
  var encounteredError = false; // Flag to track if an error occurred during iteration
  var caughtErrorObject = undefined; // Stores the error object if an error is caught

  try {
    // Obtain the iterator for the source iterable
    for (var currentIterator = sourceIterable[Symbol.iterator](), currentIterationResult; !(iterationCompleted = (currentIterationResult = currentIterator.next()).done); iterationCompleted = true) {
      resultCollection.push(currentIterationResult.value); // Add the current value to the collection
      if (maxElements && resultCollection.length === maxElements) {
        break; // Stop iterating if the maximum number of elements is reached
      }
    }
  } catch (iterationErr) {
    encounteredError = true; // Mark that an error occurred
    caughtErrorObject = iterationErr; // Store the error object
  } finally {
    try {
      // If iteration was not completed and the iterator has a 'return' method, call it to clean up.
      if (!iterationCompleted && currentIterator["return"] != null) {
        currentIterator["return"]();
      }
    } finally {
      // If an error was encountered, re-throw it after cleanup.
      if (encounteredError) {
        throw caughtErrorObject;
      }
    }
  }
  return resultCollection; // Return the array of collected elements
}

/**
 * Helper function to check if a given value is an actual JavaScript Array.
 * This is a utility often generated by transpilers.
 * @param {any} inputVal - The value to check.
 * @returns {Array|boolean} The array itself if `inputVal` is an Array, otherwise `false`.
 */
function checkIfInputIsArray(inputVal) {
  if (Array.isArray(inputVal)) {
    return inputVal; // Return the array directly if it's an array
  }
  return false; // Indicate that it's not an array
}

/**
 * The primary function to execute the problem's logic.
 * It reads numerical input, processes it, and prints a result based on a parity check.
 * @param {string} rawInputData - The complete raw input string, typically from standard input.
 */
function main(rawInputData) {
  // Divide the entire input string into an array of individual lines.
  var inputLines = rawInputData.split('\n');

  // Parse the first line to extract the count of elements (N).
  var parsedFirstLine = parseNumericStrings(inputLines[0]);
  var destructuredFirstLine = extractArrayElements(parsedFirstLine, 1);
  var elementCount = destructuredFirstLine[0]; // This variable holds the value of N

  // Parse all numbers from the input, then select the relevant 'elementCount' numbers
  // starting from the second element (index 1) of the parsed list.
  var numericElements = parseNumericStrings(rawInputData).slice(1, elementCount + 1);

  // Sort the array of numeric elements in ascending order.
  numericElements.sort(function (valueA, valueB) {
    return valueA - valueB; // Standard numerical comparison for sorting
  });

  // Calculate the differences between consecutive elements in the sorted array.
  var elementDifferences = [];
  for (var index = 0; index < elementCount - 1; index++) {
    elementDifferences.push(numericElements[index + 1] - numericElements[index]);
  }

  // Sum all the calculated differences to get a total difference.
  var totalCalculatedDifference = elementDifferences.reduce(function (accumulatorValue, currentDifference) {
    return accumulatorValue + currentDifference;
  }, 0); // Initialize the sum with zero

  // Output 'first' if the total difference is even, otherwise output 'second'.
  console.log(totalCalculatedDifference % 2 === 0 ? 'first' : 'second');
}

// Execute the main function by reading input from the standard input stream.
main(require('fs').readFileSync('/dev/stdin', 'utf8'));

/**
 * Helper function to split a string by one or more whitespace characters
 * and convert each resulting substring into an integer.
 * @param {string} inputStringForParsing - The string containing space-separated numbers.
 * @returns {Array<number>} An array of integers parsed from the input string.
 */
function parseNumericStrings(inputStringForParsing) {
  return inputStringForParsing.split(/\s+/).map(function (numericString) {
    return parseInt(numericString, 10); // Explicitly parse as base-10 integer
  });
}
